let y_eq := (h₁ ▷ (2 * x = 5 * y)).symm ▷ (5 * y = 2 * x)
let y_eq' := (y_eq ▷ (y = (2/5) * x)).symm ▷ (y = (2/5) * x)

-- From h₂, substitute y = (2/5) * x into 7 * y = 10 * z
let z_eq := (h₂ ▷ (7 * y = 10 * z)).symm ▷ (10 * z = 7 * y)
let z_eq' := (z_eq ▷ (10 * z = 7 * ((2/5) * x))).symm ▷ (10 * z = (14/5) * x)

-- Solve for z/x: z/x = (14/5)/10 = 14/50 = 7/25
let ratio := (z_eq' ▷ (z / x = (14/5) / 10)).symm ▷ (z / x = 14 / 50)
let ratio' := (ratio ▷ (14 / 50 = (7 * 2) / (25 * 2))).simp ▷ (z / x = 7 / 25)
